<?php
require __DIR__.'/../includes/study-engine/engine.php';
use EIPSI\StudyEngine\Engine as E;
$tests=0;$failures=0;
function qe_assert($v,$m='Assertion failed'){if(!$v)throw new RuntimeException($m);}
function qe_test($name,$fn){global $tests,$failures;$tests++;try{$fn();echo "PASS $name\n";}catch(Throwable $e){$failures++;echo 'FAIL '.$name.': '.$e->getMessage().' '.basename($e->getFile()).':'.$e->getLine()."\n";}}
function qe_fixture(){
 $d=json_decode(file_get_contents(glob(__DIR__.'/study-engine/fixtures/valid/01*.json')[0]),true);$d['protocol_metadata']['execution_planning']='DEPENDENCY_PLAN_V1';
 foreach($d['nodes'] as &$n)if(($n['completion_boundary']??null)==='ASSESSMENT'){
  $n['metadata']['native_questions']=array();foreach(array('Q_SOURCE','Q_A','Q_B','Q_COMMON') as $i=>$id)$n['metadata']['native_questions'][]=array('id'=>$id,'label'=>$id,'response_key'=>'R_'.$id,'value_type'=>'STRING','options'=>array(),'page'=>$i,'randomization_id'=>null);
  $n['metadata']['native_groups']=array(array('id'=>'GROUP_A','label'=>'Branch A','kind'=>'GROUP','page'=>1,'question_ids'=>array('Q_A'),'element_ids'=>array('GROUP_A','Q_A','INSTRUCTION_A')),array('id'=>'GROUP_B','label'=>'Branch B','kind'=>'GROUP','page'=>2,'question_ids'=>array('Q_B'),'element_ids'=>array('GROUP_B','Q_B')));
 }unset($n);
 foreach(array('yes'=>'GROUP_B','no'=>'GROUP_A') as $value=>$target)$d['protocol_metadata']['trajectory_conditions'][]=array('id'=>'LC_'.$value,'label'=>$value,'source'=>array('assessment_id'=>'E_SIMPLE','question_id'=>'Q_SOURCE'),'event'=>'ANSWER','priority'=>1,'reference_scope'=>'TRACK_PAST_V1','action_scope'=>'TRACK_FUTURE_V1','predicate'=>array('op'=>'EQ','reference'=>array('kind'=>'ANSWER','assessment_id'=>'E_SIMPLE','question_id'=>'Q_SOURCE'),'value'=>$value),'actions'=>array(array('type'=>'EXCLUDE_ELEMENT','target_id'=>'E_SIMPLE','element_id'=>$target)));
 return $d;
}
function qe_sim($d=null){return new E\Simulator((new E\DefinitionCompiler())->compile($d??qe_fixture()),array('created_at'=>'2026-10-12T11:00:00Z','timezone'=>'UTC','seed_hex'=>str_repeat('01',32)));}
function qe_answer($s,$answers,$serial){$id=$s->nextAction()['payload']['assessment_execution_id'];$states=array();foreach(array('Q_SOURCE','Q_A','Q_B','Q_COMMON') as $q)$states[$q]=isset($answers[$q])?'answered':'unanswered';$s->dispatch(array('id'=>'CMD_'.$serial,'kind'=>'NATIVE_LOGIC','data'=>array('block_execution_id'=>$id,'answers'=>$answers,'question_states'=>$states,'changed_questions'=>array_keys($states),'event'=>'ANSWER')));return $s->snapshot()['logical_trajectory'];}
qe_test('Unanswered source keeps alternative groups pending',function(){$s=qe_sim();$id=$s->nextAction()['payload']['assessment_execution_id'];$x=$s->snapshot()['logical_trajectory']['question_exclusions'][$id];qe_assert(($x['questions']['Q_A']??null)==='pending_condition'&&($x['questions']['Q_B']??null)==='pending_condition',json_encode($x));qe_assert(in_array('INSTRUCTION_A',$x['elements'],true));});
qe_test('Known response shows one branch and hides the other',function(){$s=qe_sim();$x=qe_answer($s,array('Q_SOURCE'=>'yes'),1);qe_assert($x['question_states']['E_SIMPLE']['Q_B']==='excluded_by_condition');qe_assert(!in_array($x['question_states']['E_SIMPLE']['Q_A'],array('excluded_by_condition','pending_condition'),true));});
qe_test('Changing branch deletes prior answers and preserves common answers',function(){$s=qe_sim();qe_answer($s,array('Q_SOURCE'=>'yes','Q_A'=>'old','Q_COMMON'=>'shared'),1);$x=qe_answer($s,array('Q_SOURCE'=>'no','Q_A'=>'old','Q_COMMON'=>'shared'),2);qe_assert(!isset($x['answers']['E_SIMPLE']['Q_A']));qe_assert($x['answers']['E_SIMPLE']['Q_COMMON']==='shared');qe_assert($x['question_states']['E_SIMPLE']['Q_A']==='excluded_by_condition');$x=qe_answer($s,array('Q_SOURCE'=>'yes','Q_COMMON'=>'shared'),3);qe_assert(!isset($x['answers']['E_SIMPLE']['Q_A']));qe_assert(!in_array($x['question_states']['E_SIMPLE']['Q_A'],array('excluded_by_condition','pending_condition'),true));});
qe_test('Checkpoint recovery preserves current exclusions and erased answers',function(){$s=qe_sim();qe_answer($s,array('Q_SOURCE'=>'yes'),1);$x=qe_answer($s,array('Q_SOURCE'=>'no','Q_A'=>'old'),2);$copy=E\Simulator::restore($s->compiled(),$s->checkpoint(),str_repeat('01',32));qe_assert($copy->snapshot()===$s->snapshot());qe_assert(!isset($x['answers']['E_SIMPLE']['Q_A']));});
qe_test('Overlapping rules retain exclusion while any rule is true',function(){$d=qe_fixture();$r=$d['protocol_metadata']['trajectory_conditions'][0];$r['id']='LC_EXTRA';$r['predicate']['value']='no';$d['protocol_metadata']['trajectory_conditions'][]=$r;$s=qe_sim($d);$x=qe_answer($s,array('Q_SOURCE'=>'no'),1);qe_assert($x['question_states']['E_SIMPLE']['Q_B']==='excluded_by_condition');});
qe_test('Source and earlier questions cannot be exclusion targets',function(){$d=qe_fixture();$d['protocol_metadata']['trajectory_conditions'][0]['actions'][0]['element_id']='Q_SOURCE';$issues=E\LogicalConditions::diagnostics($d);qe_assert(in_array('EXCLUSION_TARGET_MUST_FOLLOW_SOURCE',array_column($issues,'code'),true));});
qe_test('Exclusions reject future predicate sources and wrong events',function(){$d=qe_fixture();$d['protocol_metadata']['trajectory_conditions'][0]['predicate']['reference']['question_id']='Q_COMMON';qe_assert(in_array('EXCLUSION_REQUIRES_PAST_REFERENCE',array_column(E\LogicalConditions::diagnostics($d),'code'),true));$d=qe_fixture();$d['protocol_metadata']['trajectory_conditions'][0]['event']='COMPLETE';qe_assert(in_array('INVALID_QUESTION_EXCLUSION_TARGET',array_column(E\LogicalConditions::diagnostics($d),'code'),true));});
qe_test('Group filtering removes content and empty pages without changing page indices',function(){$d=array('elements'=>array(array('id'=>'Q_SOURCE','type'=>'text','children'=>array()),array('id'=>'PB_1','type'=>'page_break','children'=>array()),array('id'=>'GROUP_A','type'=>'group','children'=>array(array('id'=>'INSTRUCTION_A','type'=>'instruction','children'=>array()),array('id'=>'Q_A','type'=>'text','children'=>array()))),array('id'=>'PB_2','type'=>'page_break','children'=>array()),array('id'=>'Q_COMMON','type'=>'text','children'=>array())));$filtered=E\QuestionExclusions::definition($d,array('GROUP_A'));qe_assert(E\QuestionExclusions::pages($filtered)===array(0,2));qe_assert(count($d['elements'])===5);});
qe_test('Exclusions do not change stored random decisions or seeds',function(){$s=qe_sim();$before=$s->snapshot()['random_decisions'];qe_answer($s,array('Q_SOURCE'=>'yes'),1);qe_answer($s,array('Q_SOURCE'=>'no'),2);qe_assert($before===$s->snapshot()['random_decisions']);});
qe_test('Clearing the controller hides both branches and erases its prior logical value',function(){$s=qe_sim();qe_answer($s,array('Q_SOURCE'=>'yes','Q_A'=>'old'),1);$x=qe_answer($s,array(),2);qe_assert(!isset($x['answers']['E_SIMPLE']['Q_SOURCE'],$x['answers']['E_SIMPLE']['Q_A']));qe_assert($x['question_states']['E_SIMPLE']['Q_A']==='pending_condition'&&$x['question_states']['E_SIMPLE']['Q_B']==='pending_condition');});
qe_test('A jump cannot enter a question excluded by the same transition',function(){$d=qe_fixture();$d['protocol_metadata']['trajectory_conditions'][0]['actions'][]=array('type'=>'GO_QUESTION','target_id'=>'E_SIMPLE','question_id'=>'Q_B');$s=qe_sim($d);$x=qe_answer($s,array('Q_SOURCE'=>'yes'),1);qe_assert($x['navigation']===null);qe_assert($x['question_states']['E_SIMPLE']['Q_B']==='excluded_by_condition');});
qe_test('Repeated opportunities start pending and never inherit another occurrence answers',function(){
 $d=json_decode(file_get_contents(glob(__DIR__.'/study-engine/fixtures/valid/04*.json')[0]),true);$base=qe_fixture();$metadata=array_column($base['nodes'],null,'id')['E_SIMPLE']['metadata'];foreach($d['nodes'] as &$n)if($n['id']==='E_DIARY')$n['metadata']=$metadata;unset($n);$d['protocol_metadata']['execution_planning']='DEPENDENCY_PLAN_V1';$d['protocol_metadata']['trajectory_conditions']=$base['protocol_metadata']['trajectory_conditions'];foreach($d['protocol_metadata']['trajectory_conditions'] as &$r){$r['source']['assessment_id']='E_DIARY';$r['predicate']['reference']['assessment_id']='E_DIARY';$r['actions'][0]['target_id']='E_DIARY';}unset($r);
 $s=qe_sim($d);$before=$s->snapshot();$ids=array_keys($before['logical_trajectory']['question_exclusions']);qe_assert(count($ids)>1,'Repeated exclusions not initialized');$s->dispatch(array('id'=>'REPEAT_FIRST','kind'=>'NATIVE_LOGIC','data'=>array('block_execution_id'=>$ids[0],'answers'=>array('Q_SOURCE'=>'yes'),'question_states'=>array('Q_SOURCE'=>'answered'),'changed_questions'=>array('Q_SOURCE'),'event'=>'ANSWER')));$state=$s->snapshot()['logical_trajectory'];qe_assert($state['question_exclusions'][$ids[1]]['questions']['Q_A']==='pending_condition');qe_assert(empty($state['occurrences'][$ids[1]]['answers']));qe_assert($state['answers']['E_DIARY']['Q_SOURCE']==='yes');
});
qe_test('Dependent conditions settle against excluded question states in the same transition',function(){
 $d=qe_fixture();$r=$d['protocol_metadata']['trajectory_conditions'][0];$r['id']='LC_FOLLOW_EXCLUSION';$r['source']['question_id']='Q_A';$r['predicate']=array('op'=>'EQ','reference'=>array('kind'=>'QUESTION_STATE','assessment_id'=>'E_SIMPLE','question_id'=>'Q_A'),'value'=>'excluded_by_condition');$r['actions']=array(array('type'=>'EXCLUDE_ELEMENT','target_id'=>'E_SIMPLE','element_id'=>'Q_COMMON'));$d['protocol_metadata']['trajectory_conditions'][]=$r;$s=qe_sim($d);$x=qe_answer($s,array('Q_SOURCE'=>'no'),1);qe_assert($x['question_states']['E_SIMPLE']['Q_A']==='excluded_by_condition');qe_assert($x['question_states']['E_SIMPLE']['Q_COMMON']==='excluded_by_condition');
});
qe_test('Individual matrix-row exclusions retain the other rows and remove an empty matrix',function(){
 $d=array('elements'=>array(array('id'=>'MATRIX','type'=>'matrix','properties'=>array('matrix_rows'=>array(array('id'=>'ROW_A'),array('id'=>'ROW_B'))),'children'=>array())));$partial=E\QuestionExclusions::definition($d,array('ROW_A'));qe_assert(array_column($partial['elements'][0]['properties']['matrix_rows'],'id')===array('ROW_B'));$empty=E\QuestionExclusions::definition($d,array('ROW_A','ROW_B'));qe_assert($empty['elements']===array());
});
qe_test('A repeated completed opportunity gets independent exclusions without overwriting completed answers',function(){
 $s=qe_sim();qe_answer($s,array('Q_SOURCE'=>'yes'),1);$id=$s->nextAction()['payload']['assessment_execution_id'];$s->dispatch(array('id'=>'DONE_ORIGINAL','kind'=>'SUBMIT_ASSESSMENT','data'=>array('block_execution_id'=>$id,'responses'=>array('Q_AGE'=>40,'Q_WELLBEING'=>2))));$before=$s->snapshot();$s->dispatch(array('id'=>'REPEATED_NATIVE','kind'=>'NATIVE_LOGIC','data'=>array('block_execution_id'=>$id,'native_attempt_id'=>'NX_SECOND','answers'=>array('Q_SOURCE'=>'no'),'question_states'=>array('Q_SOURCE'=>'answered'),'changed_questions'=>array('Q_SOURCE'),'event'=>'ANSWER')));$state=$s->snapshot()['logical_trajectory'];qe_assert($state['native_question_exclusions']['NX_SECOND']['questions']['Q_A']==='excluded_by_condition');qe_assert($state['answers']['E_SIMPLE']===$before['logical_trajectory']['answers']['E_SIMPLE']);qe_assert($state['question_exclusions'][$id]===$before['logical_trajectory']['question_exclusions'][$id]);
});
qe_test('Randomized order permits exclusions only on tracks where the target is actually future',function(){
 $d=qe_fixture();foreach($d['nodes'] as &$n)if($n['id']==='E_SIMPLE')foreach($n['metadata']['native_questions'] as &$q)if(in_array($q['id'],array('Q_SOURCE','Q_A'),true))$q['randomization_path']=array(array('randomization_id'=>'R_ORDER','candidate_id'=>$q['id']));unset($n,$q);$r=$d['protocol_metadata']['trajectory_conditions'][0];$r['source']['question_id']='Q_A';$r['predicate']['reference']['question_id']='Q_A';$r['actions'][0]['element_id']='Q_SOURCE';$d['protocol_metadata']['trajectory_conditions']=array($r);qe_assert(!in_array('EXCLUSION_TARGET_MUST_FOLLOW_SOURCE',array_column(E\LogicalConditions::diagnostics($d),'code'),true));
 $a=$r['actions'][0];qe_assert(E\LogicalPast::actionAllows($d,$r,$a,array(),array('E_SIMPLE|R_ORDER'=>array('Q_A','Q_SOURCE'))));qe_assert(!E\LogicalPast::actionAllows($d,$r,$a,array(),array('E_SIMPLE|R_ORDER'=>array('Q_SOURCE','Q_A'))));
});
echo "$tests tests, $failures failures\n";exit($failures?1:0);
